    user_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=True)
    category_id = db.Column(db.Integer, db.ForeignKey('categories.id'), nullable=True)
    created_at = db.Column(db.DateTime, default=utc_now)
    updated_at = db.Column(db.DateTime, default=utc_now, onupdate=utc_now)
    due_date = db.Column(db.DateTime, nullable=True)
    tags = db.Column(db.String(500), nullable=True)

    user = db.relationship('User', backref='tasks')
    category = db.relationship('Category', backref='tasks')

    # ---- domain rules -------------------------------------------------------------------

    def is_overdue(self, now=None):
        now = now or utc_now()
        return bool(self.due_date and self.due_date < now and self.status not in CLOSED_STATUSES)

    def days_overdue(self, now=None):
        return ((now or utc_now()) - self.due_date).days

    # ---- serialization ------------------------------------------------------------------

    def to_dict(self):
        return {
            'id': self.id,
            'title': self.title,
            'description': self.description,
            'status': self.status,
            'priority': self.priority,
            'user_id': self.user_id,
            'category_id': self.category_id,
            'created_at': str(self.created_at),
            'updated_at': str(self.updated_at),
            'due_date': str(self.due_date) if self.due_date else None,
            'tags': self.tags.split(',') if self.tags else [],
        }

    def to_detail_dict(self):
        data = self.to_dict()
        data['overdue'] = self.is_overdue()
        return data

    def to_list_dict(self):
        data = self.to_detail_dict()
        data['user_name'] = self.user.name if self.user else None
        data['category_name'] = self.category.name if self.category else None
        return data

    def to_user_task_dict(self):
        return {
            'id': self.id,
            'title': self.title,
            'description': self.description,
            'status': self.status,
            'priority': self.priority,
            'created_at': str(self.created_at),
            'due_date': str(self.due_date) if self.due_date else None,
            'overdue': self.is_overdue(),
        }

    def to_overdue_dict(self, now):
        return {
            'id': self.id,
            'title': self.title,
            'due_date': str(self.due_date),
            'days_overdue': self.days_overdue(now),
        }

    # ---- queries ------------------------------------------------------------------------

    @classmethod
    def list_with_relations(cls):
        query = db.select(cls).options(selectinload(cls.user), selectinload(cls.category))
        return db.session.execute(query.order_by(cls.id)).scalars().all()

    @classmethod
    def list_by_user(cls, user_id):
        query = db.select(cls).where(cls.user_id == user_id).order_by(cls.id)
        return db.session.execute(query).scalars().all()

    @classmethod
    def search(cls, text=None, status=None, priority=None, user_id=None):
        query = db.select(cls)
        if text:
            pattern = f'%{text}%'
            query = query.where(db.or_(cls.title.like(pattern), cls.description.like(pattern)))
        if status:
            query = query.where(cls.status == status)
        if priority is not None:
            query = query.where(cls.priority == priority)
        if user_id is not None:
            query = query.where(cls.user_id == user_id)
        return db.session.execute(query.order_by(cls.id)).scalars().all()

    @classmethod
    def _overdue_filter(cls, now):
        return db.and_(cls.due_date.is_not(None), cls.due_date < now,
                       cls.status.not_in(CLOSED_STATUSES))

    @classmethod
    def list_overdue(cls, now):
        query = db.select(cls).where(cls._overdue_filter(now)).order_by(cls.id)
        return db.session.execute(query).scalars().all()

    @classmethod
    def count_overdue(cls, now):
        query = db.select(db.func.count()).select_from(cls).where(cls._overdue_filter(now))
        return db.session.scalar(query)

    @classmethod
    def _count_grouped(cls, *columns):
        query = db.select(*columns, db.func.count()).group_by(*columns)
        rows = db.session.execute(query).all()
        if len(columns) == 1:
            return {row[0]: row[1] for row in rows}
        return {tuple(row[:-1]): row[-1] for row in rows}

    @classmethod
    def count_by_status(cls):
        return cls._count_grouped(cls.status)

    @classmethod
    def count_by_priority(cls):
        return cls._count_grouped(cls.priority)

    @classmethod
    def count_by_user(cls):
        return cls._count_grouped(cls.user_id)

    @classmethod
    def count_by_category(cls):
        return cls._count_grouped(cls.category_id)

    @classmethod
    def count_by_user_and_status(cls):
        return cls._count_grouped(cls.user_id, cls.status)

    @classmethod
    def count_created_since(cls, since):
        query = db.select(db.func.count()).select_from(cls).where(cls.created_at >= since)
        return db.session.scalar(query)

    @classmethod
    def count_completed_since(cls, since):
        query = (db.select(db.func.count()).select_from(cls)
                 .where(cls.status == STATUS_DONE, cls.updated_at >= since))
        return db.session.scalar(query)

