import hashlib
import hmac
import re

from sqlalchemy.exc import IntegrityError
from werkzeug.security import check_password_hash, generate_password_hash

from database import db
from models.base import PersistenceMixin
from utils.constants import ROLE_USER
from utils.errors import ConflictError
from utils.time import utc_now

# Hashes written by the previous version of the app (unsalted MD5, 32 hex chars).
_LEGACY_MD5 = re.compile(r'^[0-9a-f]{32}$')


class User(PersistenceMixin, db.Model):
    __tablename__ = 'users'

    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    email = db.Column(db.String(150), unique=True, nullable=False)
    password = db.Column(db.String(255), nullable=False)
    role = db.Column(db.String(50), default=ROLE_USER)
    active = db.Column(db.Boolean, default=True)
    created_at = db.Column(db.DateTime, default=utc_now)

    # ---- serialization (never includes the password hash) -------------------------------

    def to_dict(self):
        return {
            'id': self.id,
            'name': self.name,
            'email': self.email,
            'role': self.role,
            'active': self.active,
            'created_at': str(self.created_at),
        }

    def to_contact_dict(self):
        return {'id': self.id, 'name': self.name, 'email': self.email}

    # ---- credentials --------------------------------------------------------------------

    def set_password(self, password):
        self.password = generate_password_hash(password)

    def uses_legacy_hash(self):
        return bool(_LEGACY_MD5.match(self.password or ''))

    def check_password(self, password):
        if self.uses_legacy_hash():
            # Verification-only path for rows created before the migration; re-hashed on login.
            legacy = hashlib.md5(password.encode(), usedforsecurity=False).hexdigest()
            return hmac.compare_digest(self.password, legacy)
        return check_password_hash(self.password, password)

    @classmethod
    def authenticate(cls, email, password):
        """Return the user when the credentials match, upgrading legacy hashes; else None."""
        user = cls.find_by_email(email)
        if user is None or not user.check_password(password):
            return None
        if user.uses_legacy_hash():
            user.set_password(password)
            db.session.commit()
        return user

    # ---- queries / persistence ----------------------------------------------------------

    @classmethod
    def find_by_email(cls, email):
        return db.session.execute(db.select(cls).where(cls.email == email)).scalar_one_or_none()

    @classmethod
    def email_taken(cls, email, exclude_id=None):
        user = cls.find_by_email(email)
        return user is not None and user.id != exclude_id

    def save(self):
        try:
            return super().save()
        except IntegrityError:
            db.session.rollback()
