"""Report assembly: aggregations across tasks, users and categories."""
from datetime import timedelta

from models.category import Category
from models.task import Task
from models.user import User
from utils.constants import (HIGH_PRIORITY_MAX, PRIORITY_LABELS, RECENT_ACTIVITY_DAYS,
                             STATUS_CANCELLED, STATUS_DONE, STATUS_IN_PROGRESS, STATUS_PENDING,
                             TASK_STATUSES)
from utils.time import utc_now


def percentage(part, total):
    if total == 0:
        return 0
    return round((part / total) * 100, 2)


def _status_counts(counts):
    return {status: counts.get(status, 0) for status in TASK_STATUSES}


def task_stats():
    total = Task.count()
    by_status = _status_counts(Task.count_by_status())
    return {
        'total': total,
        **by_status,
        'overdue': Task.count_overdue(utc_now()),
        'completion_rate': percentage(by_status[STATUS_DONE], total),
    }


def _user_productivity():
    counts = Task.count_by_user_and_status()
    stats = []
    for user in User.list_all():
        total = sum(n for (user_id, _status), n in counts.items() if user_id == user.id)
        completed = counts.get((user.id, STATUS_DONE), 0)
        stats.append({
            'user_id': user.id,
            'user_name': user.name,
            'total_tasks': total,
            'completed_tasks': completed,
            'completion_rate': percentage(completed, total),
        })
    return stats


def summary():
    now = utc_now()
    since = now - timedelta(days=RECENT_ACTIVITY_DAYS)
    by_priority = Task.count_by_priority()
    overdue_tasks = Task.list_overdue(now)
    return {
        'generated_at': str(now),
        'overview': {
            'total_tasks': Task.count(),
            'total_users': User.count(),
            'total_categories': Category.count(),
        },
        'tasks_by_status': _status_counts(Task.count_by_status()),
        'tasks_by_priority': {label: by_priority.get(priority, 0)
                              for priority, label in PRIORITY_LABELS.items()},
        'overdue': {
            'count': len(overdue_tasks),
            'tasks': [task.to_overdue_dict(now) for task in overdue_tasks],
        },
        'recent_activity': {
            'tasks_created_last_7_days': Task.count_created_since(since),
            'tasks_completed_last_7_days': Task.count_completed_since(since),
        },
        'user_productivity': _user_productivity(),
    }


def user_report(user):
    tasks = Task.list_by_user(user.id)
    now = utc_now()
    by_status = {status: 0 for status in TASK_STATUSES}
    for task in tasks:
        if task.status in by_status:
            by_status[task.status] += 1
    done = by_status[STATUS_DONE]
    return {
        'user': user.to_contact_dict(),
        'statistics': {
            'total_tasks': len(tasks),
            'done': done,
            'pending': by_status[STATUS_PENDING],
            'in_progress': by_status[STATUS_IN_PROGRESS],
            'cancelled': by_status[STATUS_CANCELLED],
            'overdue': sum(1 for task in tasks if task.is_overdue(now)),
            'high_priority': sum(1 for task in tasks if task.priority <= HIGH_PRIORITY_MAX),
            'completion_rate': percentage(done, len(tasks)),
        },
    }

