"""Input validation shared by the controllers. Validators raise domain errors (400/404)."""
from datetime import datetime

from flask import request

from models.category import Category
from models.user import User
from utils.constants import (COLOR_PATTERN, DATE_FORMAT, DEFAULT_PRIORITY, EMAIL_PATTERN,
                             MAX_PRIORITY, MAX_TITLE_LENGTH, MIN_PASSWORD_LENGTH, MIN_PRIORITY,
                             MIN_TITLE_LENGTH, STATUS_PENDING, TASK_STATUSES, USER_ROLES)
from utils.errors import NotFoundError, ValidationError

DATE_ERROR_CREATE = 'Formato de data inválido. Use YYYY-MM-DD'
DATE_ERROR_UPDATE = 'Formato de data inválido'


# ---- generic -----------------------------------------------------------------------------

def json_body(allow_empty=False):
    data = request.get_json()
    if isinstance(data, dict) and (data or allow_empty):
        return data
    raise ValidationError('Dados inválidos')


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def int_query_arg(name, message):
    raw = request.args.get(name, '')
    if not raw:
        return None
    try:
        return int(raw)
    except ValueError:
        raise ValidationError(message)


def _existing(model, entity_id, message):
    """Return the referenced id (None when empty) after checking that the row exists."""
    if not entity_id:
        return None
    if isinstance(entity_id, bool) or not isinstance(entity_id, (int, str)) \
            or model.get_by_id(entity_id) is None:
        raise NotFoundError(message)
    return entity_id


# ---- tasks -------------------------------------------------------------------------------

def _title(value):
    if not isinstance(value, str):
        raise ValidationError('Título inválido')
    if len(value) < MIN_TITLE_LENGTH:
        raise ValidationError('Título muito curto')
    if len(value) > MAX_TITLE_LENGTH:
        raise ValidationError('Título muito longo')
    return value


def _status(value):
    if not isinstance(value, str) or value not in TASK_STATUSES:
        raise ValidationError('Status inválido')
    return value


def _priority(value):
    if not _is_int(value) or not MIN_PRIORITY <= value <= MAX_PRIORITY:
        raise ValidationError('Prioridade deve ser entre 1 e 5')
    return value


def _due_date(value, message):
    if not value:
        return None
    if not isinstance(value, str):
        raise ValidationError(message)
    try:
        return datetime.strptime(value, DATE_FORMAT)
    except ValueError:
        raise ValidationError(message)


def _tags(value):
    if isinstance(value, list):
        if not all(isinstance(tag, str) for tag in value):
            raise ValidationError('Tags inválidas')
        return ','.join(value)
    if value is None or isinstance(value, str):
        return value
    raise ValidationError('Tags inválidas')


def validate_new_task(data):
    title = data.get('title')
    if not title:
        raise ValidationError('Título é obrigatório')
    fields = {
        'title': _title(title),
        'description': data.get('description', ''),
        'status': _status(data.get('status', STATUS_PENDING)),
        'priority': _priority(data.get('priority', DEFAULT_PRIORITY)),
        'user_id': _existing(User, data.get('user_id'), 'Usuário não encontrado'),
        'category_id': _existing(Category, data.get('category_id'), 'Categoria não encontrada'),
    }
    if data.get('due_date'):
        fields['due_date'] = _due_date(data['due_date'], DATE_ERROR_CREATE)
    if data.get('tags'):
        fields['tags'] = _tags(data['tags'])
    return fields


def validate_task_changes(data):
    changes = {}
    if 'title' in data:
        changes['title'] = _title(data['title'])
    if 'description' in data:
        changes['description'] = data['description']
    if 'status' in data:
        changes['status'] = _status(data['status'])
    if 'priority' in data:
        changes['priority'] = _priority(data['priority'])
    if 'user_id' in data:
        changes['user_id'] = _existing(User, data['user_id'], 'Usuário não encontrado')
    if 'category_id' in data:
        changes['category_id'] = _existing(Category, data['category_id'],
                                           'Categoria não encontrada')
    if 'due_date' in data:
        changes['due_date'] = _due_date(data['due_date'], DATE_ERROR_UPDATE)
    if 'tags' in data:
        changes['tags'] = _tags(data['tags'])
    return changes


def validate_search_args():
    return {
        'text': request.args.get('q', ''),
        'status': request.args.get('status', ''),
        'priority': int_query_arg('priority', 'Prioridade inválida'),
        'user_id': int_query_arg('user_id', 'Usuário inválido'),
    }


# ---- users -------------------------------------------------------------------------------

def _email(value):
    if not isinstance(value, str) or not EMAIL_PATTERN.match(value):
        raise ValidationError('Email inválido')
    return value


def _password(value, message):
    if not isinstance(value, str) or len(value) < MIN_PASSWORD_LENGTH:
        raise ValidationError(message)
    return value


def _role(value):
    if not isinstance(value, str) or value not in USER_ROLES:
        raise ValidationError('Role inválido')
    return value


def _name(value):
    if not isinstance(value, str) or not value.strip():
        raise ValidationError('Nome é obrigatório')
    return value


def validate_new_user(data):
    """Validate presence/format; email uniqueness and role are checked by the controller."""
    name, email, password = data.get('name'), data.get('email'), data.get('password')
    if not name:
        raise ValidationError('Nome é obrigatório')
    if not email:
        raise ValidationError('Email é obrigatório')
    if not password:
        raise ValidationError('Senha é obrigatória')
    return {
        'name': _name(name),
        'email': _email(email),
        'password': _password(password, 'Senha deve ter no mínimo 4 caracteres'),
    }


def validate_user_changes(data):
    changes = {}
    if 'name' in data:
        changes['name'] = _name(data['name'])
    if 'email' in data:
        changes['email'] = _email(data['email'])
    if 'password' in data:
        changes['password'] = _password(data['password'], 'Senha muito curta')
    if 'role' in data:
        changes['role'] = _role(data['role'])
    if 'active' in data:
        if not isinstance(data['active'], bool):
            raise ValidationError('Campo active inválido')
        changes['active'] = data['active']
    return changes


def validate_role(value):
    return _role(value)


def validate_credentials(data):
    email, password = data.get('email'), data.get('password')
    if not email or not password or not isinstance(email, str) or not isinstance(password, str):
        raise ValidationError('Email e senha são obrigatórios')
    return email, password


# ---- categories --------------------------------------------------------------------------

def _color(value):
    if not isinstance(value, str) or not COLOR_PATTERN.match(value):
        raise ValidationError('Cor inválida')
    return value


def validate_new_category(data, default_color):
    name = data.get('name')
    if not name:
        raise ValidationError('Nome é obrigatório')
    return {
        'name': _name(name),
        'description': data.get('description', ''),
        'color': _color(data.get('color', default_color)),
    }


def validate_category_changes(data):
    changes = {}
    if 'name' in data:
        changes['name'] = _name(data['name'])
    if 'description' in data:
