"""Report unused imports per file and top-level functions/classes never referenced elsewhere."""
import ast
import os
import sys

ROOT = sys.argv[1]
files = []
for d, dirs, names in os.walk(ROOT):
    dirs[:] = [x for x in dirs if x not in (".venv", ".git", ".claude", "__pycache__", "instance")]
    files += [os.path.join(d, n) for n in names if n.endswith(".py")]

sources = {f: open(f).read() for f in files}
all_text = "\n".join(sources.values())
for f, src in sorted(sources.items()):
    tree = ast.parse(src)
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | \
           {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                name = (alias.asname or alias.name).split(".")[0]
                if name not in used and not f.endswith("__init__.py") and "noqa" not in src.splitlines()[node.lineno - 1]:
                    print(f"UNUSED IMPORT {os.path.relpath(f, ROOT)}:{node.lineno} {name}")
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
            if all_text.count(node.name) < 2:
                print(f"UNREFERENCED {os.path.relpath(f, ROOT)}:{node.lineno} {node.name}")
        if isinstance(node, ast.ClassDef):
            for item in node.body:
                if isinstance(item, ast.FunctionDef) and not item.name.startswith("__") \
                        and all_text.count(item.name) < 2:
                    print(f"UNREFERENCED METHOD {os.path.relpath(f, ROOT)}:{item.lineno} {node.name}.{item.name}")
print("scanned", len(files), "files")

